import{_ as t,o as d,c as a,a2 as r}from"./chunks/framework.D7EuCHIT.js";const y=JSON.parse('{"title":"宿主组件与平台适配","description":"","frontmatter":{},"headers":[],"relativePath":"developers/components.md","filePath":"developers/components.md","lastUpdated":1795341523000}'),o={name:"developers/components.md"};function c(s,e,l,i,n,h){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="宿主组件与平台适配" tabindex="-1">宿主组件与平台适配 <a class="header-anchor" href="#宿主组件与平台适配" aria-label="Permalink to &quot;宿主组件与平台适配&quot;">​</a></h1><p>此页按界面区域列出宿主现有的公开配置和扩展入口。参数类型、默认值和约束以<a href="/LyraPlayer-docs-site/config/reference/">配置参考</a>为准。</p><table tabindex="0"><thead><tr><th>组件或区域</th><th>配置表</th><th>公开行为或扩展</th></tr></thead><tbody><tr><td>外壳、抽屉和卡片布局</td><td><code>shell</code>、<code>geometry</code></td><td><a href="/LyraPlayer-docs-site/plugins/navigation">导航扩展</a></td></tr><tr><td>底部播放条</td><td><code>dock</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/playback">播放接口</a></td></tr><tr><td>播放页、封面和流动背景</td><td><code>player</code>、<code>cover_fx</code>、<code>flow</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制</a></td></tr><tr><td>歌词</td><td><code>player</code> 的 <code>lyric_*</code> 参数</td><td>歌词资源与播放进度由宿主管理</td></tr><tr><td>展开面板</td><td><code>sheet</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/styles">Scene 绘制协议</a></td></tr><tr><td>资料库和搜索</td><td><code>search</code>、<code>profile</code>、<code>scroll</code></td><td><a href="/LyraPlayer-docs-site/plugins/media">媒体资源</a>、<a href="/LyraPlayer-docs-site/plugins/personal-library">私人资料库</a></td></tr><tr><td>设置页</td><td><code>settings</code>、<code>theme</code></td><td><a href="/LyraPlayer-docs-site/plugins/settings-page">声明式设置页协议</a></td></tr><tr><td>样式选择器</td><td><code>style</code></td><td>宿主提供 Bloom、Ember 和沉浸样式。插件可以向同一选择器提供样式描述</td></tr></tbody></table><h2 id="配置与应用样式" tabindex="-1">配置与应用样式 <a class="header-anchor" href="#配置与应用样式" aria-label="Permalink to &quot;配置与应用样式&quot;">​</a></h2><ul><li>改全局配色用 <code>theme</code>。改尺寸和间距用对应区域的表。配置读写遵循<a href="/LyraPlayer-docs-site/plugins/config-schema">配置接口和字段约束</a>。</li><li>播放页整体样式用<a href="/LyraPlayer-docs-site/plugins/styles">样式与绘制接口</a>。需要自绘时通过 Scene 提交画面。</li><li>声明式设置行由宿主绘制。插件接收激活或确认消息，并处理校验、持久化和失败反馈。行标记、禁用状态、当前值和可用操作见<a href="/LyraPlayer-docs-site/plugins/settings-page">设置页协议</a>。</li></ul><h2 id="android-布局和能力" tabindex="-1">Android 布局和能力 <a class="header-anchor" href="#android-布局和能力" aria-label="Permalink to &quot;Android 布局和能力&quot;">​</a></h2><p>宿主从 Android 8（API 26）起支持，正式插件应提供 <code>arm64-v8a</code> 构建。插件使用公开帧和布局数据适配当前窗口尺寸及安全区。横屏、竖屏和有系统栏遮挡的窗口都应使用实际可用空间做绘制和命中。尺寸单位查对应配置键的定义，绘制坐标查 Scene 协议。</p><p>调用 Android 能力时，遵循<a href="/LyraPlayer-docs-site/plugins/android">Android 平台契约</a>的线程、引用和权限要求。能力可用性按运行设备版本及宿主声明判断。</p>',8)])])}const f=t(o,[["render",c]]);export{y as __pageData,f as default};
